<template><AppShell><view class="page-heading"><text class="eyebrow">人物索引 / THE ARCHIVE</text><text class="page-title">山河之间，遇见他们</text><text class="muted">从姓名、别名或出生省份出发，选择一段人生。</text></view><view class="filter-panel"><view class="search-field"><image src="/static/icons/search.svg"/><input v-model="query" placeholder="搜索姓名或别名，如：博古" confirm-type="search" aria-label="搜索人物" @confirm="load"/><button v-if="query" class="clear-button" @tap="query=''">×</button></view><view class="chips"><button v-for="p in provinces" :key="p" :class="{active:province===p}" @tap="province=p">{{p}}</button></view></view><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else><view class="list-summary"><text>{{items.length}} 位人物</text><text>当前筛选范围 · 不代表全国统计</text></view><view v-if="items.length" class="people-grid"><PersonCard v-for="(p,i) in items" :key="p.id" :person="p" :index="i"/></view><StatePanel v-else title="暂未找到对应人物" message="试试其他姓名、别名，或切换省份。未收录不等于人数为零。"/></template></AppShell></template>
<script setup>
import {ref,watch} from 'vue';import {onLoad,onShareAppMessage} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import PersonCard from '../../components/PersonCard.vue';import StatePanel from '../../components/StatePanel.vue';import {api} from '../../lib/api.js'
const items=ref([]),query=ref(''),province=ref('全部'),provinces=['全部','江苏','湖北','待核'],loading=ref(true),error=ref('');let sequence=0,timer
async function load(){const token=++sequence;loading.value=true;error.value='';try{const data=await api('people',{q:query.value,province:province.value==='全部'?'':province.value,limit:100});if(token===sequence)items.value=data.items}catch(e){if(token===sequence)error.value=e.message}finally{if(token===sequence)loading.value=false}}
watch([query,province],()=>{sequence++;clearTimeout(timer);timer=setTimeout(load,220)});onLoad(load);onShareAppMessage(()=>({title:'英迹 · 人物索引',path:'/pages/people/index'}))
</script>
